// CveContentType is a source of CVE information
type CveContentType string

// NewCveContentType create CveContentType
func NewCveContentType(name string) CveContentType {
	switch name {
	case "nvd":
		return Nvd
	case "jvn":
		return Jvn
	case "redhat", "centos", "alma", "rocky":
		return RedHat
	case "fedora":
		return Fedora
	case "oracle":
		return Oracle
	case "ubuntu":
		return Ubuntu
	case "debian", "debian-oval":
		return Debian
	case "redhat_api":
		return RedHatAPI
	case "debian_security_tracker":
		return DebianSecurityTracker
	case "ubuntu_api":
		return UbuntuAPI
	case constant.OpenSUSE, constant.OpenSUSELeap, constant.SUSEEnterpriseServer, constant.SUSEEnterpriseDesktop:
		return SUSE
	case "microsoft":
		return Microsoft
	case "wordpress":
		return WpScan
	case "amazon":
		return Amazon
	case "trivy":
		return Trivy
	case "trivy:debian":
		return TrivyDebian
	case "trivy:ubuntu":
		return TrivyUbuntu
	case "trivy:nvd":
		return TrivyNVD
	case "trivy:redhat":
		return TrivyRedHat
	case "trivy:ghsa":
		return TrivyGHSA
	case "trivy:oracle-oval":
		return TrivyOracleOVAL
	case "GitHub":
		return Trivy
	default:
		if strings.HasPrefix(name, "trivy:") {
			return CveContentType(name)
		}
		return Unknown
	}
}

// GetCveContentTypes return CveContentTypes
func GetCveContentTypes(family string) []CveContentType {
	switch family {
	case "trivy":
		return []CveContentType{
			TrivyDebian,
			TrivyUbuntu,
			TrivyNVD,
			TrivyRedHat,
			TrivyGHSA,
			TrivyOracleOVAL,
			Trivy,
		}
	case constant.RedHat, constant.CentOS, constant.Alma, constant.Rocky:
		return []CveContentType{RedHat, RedHatAPI}
	case constant.Fedora:
		return []CveContentType{Fedora}
	case constant.Oracle:
		return []CveContentType{Oracle}
	case constant.Amazon:
		return []CveContentType{Amazon}
	case constant.Debian, constant.Raspbian:
		return []CveContentType{Debian, DebianSecurityTracker}
	case constant.Ubuntu:
		return []CveContentType{Ubuntu, UbuntuAPI}
	case constant.OpenSUSE, constant.OpenSUSELeap, constant.SUSEEnterpriseServer, constant.SUSEEnterpriseDesktop:
		return []CveContentType{SUSE}
	case constant.Windows:
		return []CveContentType{Microsoft}
	default:
		return nil
	}
}

