func (d libraryDetector) getVulnDetail(tvuln types.DetectedVulnerability) (vinfo models.VulnInfo, err error) {
	vul, err := trivydb.Config{}.GetVulnerability(tvuln.VulnerabilityID)
	if err != nil {
		return vinfo, err
	}

	vinfo.CveID = tvuln.VulnerabilityID
	vinfo.CveContents = getCveContents(tvuln.VulnerabilityID, vul)
	vinfo.LibraryFixedIns = []models.LibraryFixedIn{
		{
			Key:     d.scanner.GetLibraryKey(),
			Name:    tvuln.PkgName,
			FixedIn: tvuln.FixedVersion,
			Path:    d.scanner.LockfilePath,
		},
	}
	return vinfo, nil
}

func getCveContents(cveID string, vul trivydbTypes.Vulnerability) (contents map[models.CveContentType][]models.CveContent) {
	contents = models.CveContents{}
	refs := models.References{}
	for _, refURL := range vul.References {
		refs = append(refs, models.Reference{Source: "trivy", Link: refURL})
	}
	sort.Slice(refs, func(i, j int) bool { return refs[i].Link < refs[j].Link })

	sources := map[trivydbTypes.SourceID]struct{}{}
	for source := range vul.VendorSeverity {
		sources[source] = struct{}{}
	}
	for source := range vul.CVSS {
		sources[source] = struct{}{}
	}
	if len(sources) == 0 {
		contents[models.Trivy] = []models.CveContent{{
			Type:          models.Trivy,
			CveID:         cveID,
			Title:         vul.Title,
			Summary:       vul.Description,
			Cvss3Severity: vul.Severity,
			References:    refs,
			Published:     trivyDate(vul.PublishedDate),
			LastModified:  trivyDate(vul.LastModifiedDate),
		}}
		return contents
	}

	orderedSources := make([]string, 0, len(sources))
	for source := range sources {
		orderedSources = append(orderedSources, string(source))
	}
	sort.Strings(orderedSources)
	for _, source := range orderedSources {
		sourceID := trivydbTypes.SourceID(source)
		contentType := models.NewCveContentType("trivy:" + strings.ToLower(source))
		content := models.CveContent{
			Type:         contentType,
			CveID:        cveID,
			Title:        vul.Title,
			Summary:      vul.Description,
			References:   refs,
			Published:    trivyDate(vul.PublishedDate),
			LastModified: trivyDate(vul.LastModifiedDate),
		}
		if severity, ok := vul.VendorSeverity[sourceID]; ok && severity != trivydbTypes.SeverityUnknown {
			content.Cvss3Severity = strings.ToUpper(severity.String())
		} else if len(orderedSources) == 1 {
			content.Cvss3Severity = strings.ToUpper(vul.Severity)
		}
		if cvss, ok := vul.CVSS[sourceID]; ok {
			content.Cvss2Score = cvss.V2Score
			content.Cvss2Vector = cvss.V2Vector
			content.Cvss3Score = cvss.V3Score
			content.Cvss3Vector = cvss.V3Vector
		}
		contents[contentType] = []models.CveContent{content}
	}
	return contents
}

